export const mjStyles = [{"code": "3449424109", "name": "Monochrome haze", "thumbnail": "data:image/webp;base64,"}, {"code": "2467500163", "name": "Light trails", "thumbnail": "data:image/webp;base64,"}, {"code": "3467997870", "name": "Golden blur", "thumbnail": "data:image/webp;base64,"}, {"code": "1641024569", "name": "Sunlit film", "thumbnail": "data:image/webp;base64,"}, {"code": "2195645511", "name": "Neon dream", "thumbnail": "data:image/webp;base64,"}, {"code": "2725932320", "name": "Architectural sketch", "thumbnail": "data:image/webp;base64,"}];
export function normalizeStyle(value){const code=String(value||'').trim().replace(/^--sref\s+/i,'');if(/^\d{1,20}$/.test(code))return code;if(code.length>2000||/[\s<>"']/u.test(code))throw Error('Enter one numeric style code or a public HTTPS image URL.');try{const u=new URL(code);if(u.protocol==='https:'&&!u.username&&!u.password)return u.href;}catch{}throw Error('Enter one numeric style code or a public HTTPS image URL.');}
export function applyStyle(prompt,code){const clean=prompt.replace(/\s*--sref\b[^\n]*?(?=\s+--[a-z]|$)/gi,'').trim();return clean+(code?' --sref '+normalizeStyle(code):'')}
export function validateCustomStyles(values=[]){if(!Array.isArray(values)||values.length>100)throw Error('A workspace can contain up to 100 custom styles.');return values.map(s=>{if(typeof s.name!=='string'||!s.name.trim()||s.name.length>80)throw Error('Invalid custom style name.');if(typeof s.thumbnail!=='string'||s.thumbnail.length>2000000||!/^data:image\/(png|jpeg|webp);base64,[A-Za-z0-9+/=]+$/.test(s.thumbnail))throw Error('Invalid custom style thumbnail.');return {name:s.name.trim(),code:normalizeStyle(s.code),thumbnail:s.thumbnail};});}
